const rows = $input.all().map(x => x.json);
const chatId = 'REDACTED_TELEGRAM_CHAT_ID'; // ID Умара

// Вычисляем ЗАВТРАШНЮЮ дату (с учетом часового пояса Екатеринбурга +5)
const now = new Date();
const ufaNow = new Date(now.getTime() + 5 * 60 * 60 * 1000);
const tomorrow = new Date(ufaNow);
tomorrow.setUTCDate(tomorrow.getUTCDate() + 1);
const tomorrowISO = tomorrow.toISOString().split('T')[0];

const tomorrowTasks = rows.filter(b => String(b['Дата'] || '').trim() === tomorrowISO && String(b['Статус']).trim() === 'Открыто');

let text = '🌙 Ассаляму алейкум, Умар!\\n\\n';
text += '📅 *Твои задачи на завтра:*\\n';

if (tomorrowTasks.length === 0) {
  text += '☕ На завтра задач нет. Отдыхай, иншаАллах.';
} else {
  tomorrowTasks.forEach((b, i) => {
    const sum = Number(b['Сумма']) || 0;
    const sumStr = sum > 0 ? ` (Сумма: ${sum} руб.)` : '';
    text += `\\n${i+1}. 📌 ${b['Описание']}${sumStr}`;
  });
}

text += '\\n\\n🤲 Пусть Аллах облегчит твои дела!';

return [{ json: { chatId, text } }];

const rows = $input.all().map(x => x.json);
const chatId = 'REDACTED_TELEGRAM_CHAT_ID'; // ID Умара

// Настройки дат для недели
const now = new Date();
const ufaNow = new Date(now.getTime() + 5 * 60 * 60 * 1000);
const weekAgo = new Date(ufaNow);
weekAgo.setUTCDate(weekAgo.getUTCDate() - 7);
const weekAgoISO = weekAgo.toISOString().split('T')[0];
const todayISO = ufaNow.toISOString().split('T')[0];
const nextWeek = new Date(ufaNow);
nextWeek.setUTCDate(nextWeek.getUTCDate() + 7);
const nextWeekISO = nextWeek.toISOString().split('T')[0];

let completedThisWeek = [];
let tasksNextWeek = [];
let totalIncome = 0;
let totalExpense = 0;
let categoriesExpense = {};
let incomeSources = {};

// Берем ТОЛЬКО активные записи для расчетов
const activeRows = rows.filter(b => String(b['Статус'] || '').trim() === 'Открыто');

for (const b of activeRows) {
  const date = String(b['Дата'] || '').trim();
  const type = String(b['Тип'] || '').trim();
  const amount = Number(b['Сумма']) || 0;
  const category = String(b['Категория'] || 'Прочее').trim();
  const desc = String(b['Описание'] || 'Без описания').trim();

  // 1. Задачи на следующую неделю
  if (date > todayISO && date <= nextWeekISO && type === 'Задача') {
    tasksNextWeek.push(`[${date}] ${desc}`);
  }

  // 2. Деньги (только активные)
  if (date >= weekAgoISO && date <= todayISO) {
    if (type === 'Доход' && amount > 0) {
      totalIncome += amount;
      const source = desc.replace(/[0-9]/g, '').trim();
      incomeSources[source] = (incomeSources[source] || 0) + amount;
    }
    if (type === 'Расход' && amount > 0) {
      totalExpense += amount;
      categoriesExpense[category] = (categoriesExpense[category] || 0) + amount;
    }
  }
}

// Баланс фонда (все активные Доходы минус все активные Расходы)
let totalFund = 0;
for (const b of activeRows) {
  const type = String(b['Тип'] || '').trim();
  const amount = Number(b['Сумма']) || 0;
  if (type === 'Доход') totalFund += amount;
  if (type === 'Расход') totalFund -= amount;
}

// Выполненные задачи за неделю (закрытые)
const closedThisWeek = rows.filter(b => {
  const date = String(b['Дата'] || '').trim();
  return String(b['Статус']).trim() === 'Закрыто' && date >= weekAgoISO && date <= todayISO && String(b['Тип']).trim() === 'Задача';
});

// Формируем красивый текст
let text = 'Ассаляму алейкум, Умар! Отчет за неделю:\n\n';
text += `✅ Выполнено задач: ${closedThisWeek.length}\n`;
if (closedThisWeek.length > 0) closedThisWeek.forEach(t => text += `   - ${t['Описание']}\n`);
text += '\n';

text += `📅 Задачи на след. неделю (${tasksNextWeek.length}):\n`;
if (tasksNextWeek.length > 0) tasksNextWeek.forEach(t => text += `   - ${t}\n`);
else text += '   - Задач нет\n';
text += '\n';

text += `💰 В фонде сейчас (активные): ${totalFund} руб.\n`;
text += `📥 Пришло за неделю: ${totalIncome} руб.\n`;
for (const [source, amt] of Object.entries(incomeSources)) {
  text += `   - От: ${source} — ${amt} руб.\n`;
}

text += `📤 Ушло за неделю: ${totalExpense} руб.\n`;
for (const [cat, amt] of Object.entries(categoriesExpense)) {
  text += `   - ${cat}: ${amt} руб.\n`;
}

text += '\nПусть Аллах примет ваши благие дела и дарует баракат!';
return [{ json: { chatId, text } }];
